def code(t):
 for line in t.splitlines():
  a=D.add_paragraph();a.paragraph_format.space_after=Pt(1);a.paragraph_format.line_spacing=1
  r=a.add_run(line);r.font.name='Courier New';r.font.size=Pt(9)
def table(headers,rows,widths):
 t=D.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
 for i,(x,w) in enumerate(zip(headers,widths)):t.columns[i].width=Inches(w);t.rows[0].cells[i].text=x
 for row in rows:
  cells=t.add_row().cells
  for i,v in enumerate(row):cells[i].text=str(v)
 for n,row in enumerate(t.rows):
  pr=row._tr.get_or_add_trPr();flag=OxmlElement('w:cantSplit');pr.append(flag)
  if n==0:pr.append(OxmlElement('w:tblHeader'))
  for i,c in enumerate(row.cells):
   c.width=Inches(widths[i]);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   tc=c._tc.get_or_add_tcPr();shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'333333' if n==0 else ('F3F3F3' if n%2==0 else 'FFFFFF'));tc.append(shade)
   borders=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'D9D9D9');borders.append(el)
   tc.append(borders);mar=OxmlElement('w:tcMar')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge);el.set(qn('w:w'),'100');el.set(qn('w:type'),'dxa');mar.append(el)
   tc.append(mar)
   for a in c.paragraphs:
    a.paragraph_format.space_after=Pt(2);a.paragraph_format.line_spacing=1.05
    for r in a.runs:r.font.size=Pt(10);r.bold=n==0;r.font.color.rgb=RGBColor.from_string('FFFFFF' if n==0 else '000000')
 p('')
D.add_heading('Daddu Charger integration guide',0)
p('UOCSM - Daddu Charger', 'Subtitle')
p('For the store owner, Meta account manager, website developer and support team')
h('Keep the website and employee system separate')
p('The existing Next.js website remains the public storefront. UOCSM is a separate employee application with its own login, database and deployment. Customers use a small chat widget on the website or message the store through WhatsApp, Instagram or Facebook. Staff reply from one UOCSM inbox.')
p('The website developer does not need to rebuild the storefront inside UOCSM. The first connection is a widget script. Orders and customer login are not automatically shared; order synchronization is a separate future connector.')
table(['Audience','Your responsibility'],[['Website developer','Host the support app, provide HTTPS, install the widget and verify browser security settings.'],['Meta manager','Choose the correct business assets, supply credentials in the admin form and configure webhook subscriptions.'],['Store admin','Create staff accounts, set response rules and check the dashboard and queue health.'],['Support agent','Sign in to UOCSM, handle assigned conversations and review personal dashboard statistics.']],[1.45,5.45])
h('Read this first')
p('One technical handoff is required before a Meta-only user can finish setup: the developer must provide a working public HTTPS support address. After that, the Meta manager can use the configuration forms in UOCSM without editing server files.')
p('Current status: website chat works locally; Meta text adapters are implemented but not live verified. Media, WhatsApp templates and automatic order synchronization are unfinished. This guide distinguishes setup from proof that a real message works.')
h('Where to go')
p('Pages 2–3: website and hosting handoff. Page 4: shared Meta setup. Pages 5–7: each channel. Page 8: staff dashboards. Pages 9–10: testing, troubleshooting and reference links.')
page('1 Website and employee application layout')
p('Use two addresses under the store’s domain. The addresses below are examples; the developer must replace them with the actual domains.')
table(['Purpose','Example address','Who uses it'],[['Next.js storefront','https://www.your-store.com','Customers'],['Employee application','https://support.your-store.com','Admins and agents'],['Public chat frame','https://support.your-store.com/widget','Website visitors'],['Meta webhook receiver','Support origin plus /webhooks/channel','Meta servers']],[1.4,3.35,2.15])
h('How a conversation travels')
p('Website visitor → chat widget on the Next.js site → UOCSM database and assignment engine → assigned employee inbox → reply back to the widget.')
p('WhatsApp, Instagram or Facebook customer → Meta → the corresponding UOCSM webhook → durable message queue → the same assignment engine and employee inbox → Meta send API → customer.')
h('One time developer checklist')
step(1,'Deploy UOCSM separately from the Next.js website, using Node.js 24 or later and persistent storage. The current implementation requires one running application process; do not scale it to multiple replicas or an ephemeral serverless filesystem.')
step(2,'Create the support subdomain, install a valid HTTPS certificate and route it to the UOCSM server. Keep the background process running continuously. Public webhooks must be reachable without a staff login, CAPTCHA or access gateway; their signatures provide authentication.')
step(3,'Set PUBLIC_BASE_URL to the support HTTPS origin and COOKIE_SECURE=true in the server environment. Do not put secrets in NEXT_PUBLIC variables. Keep staff session cookies restricted to the support host; do not set a shared parent-domain cookie.')
step(4,'Use a persistent data directory. Back up the database and protect data/integration.key separately. That key is required to restore the encrypted integration settings. Never publish either file through the website.')
step(5,'Give the store admin the support URL and initial login securely. Create individual staff accounts before daily use. Install the widget using page 3.')
p('Production readiness still needs monitoring, off-machine backups, restoration tests, proxy rate-limit review and real channel testing. The local load test is not a guarantee of zero lost messages.')
page('2 Add chat to the Nextjs website')
p('Owner: the website developer. Keep the existing layout and page content. Add this script once in the root layout for an App Router project, replacing only the example support origin. A Pages Router project can place the same Script component in pages/_app.tsx.')
code('''import Script from 'next/script';

// Inside the existing root layout body, after {children}:
<Script
  id="daddu-support-chat"
  src="https://support.your-store.com/embed.js"
  strategy="afterInteractive"
/>''')
p('The script adds a floating chat button and loads /widget inside an iframe. Customer messaging requests originate inside that support-hosted frame, so the store does not need to expose employee sessions or Meta tokens and normally does not need cross-origin API access.')
h('Developer checks')
step(1,'Allow the support origin in the storefront’s script-src and frame-src Content Security Policy. Verify that the floating button can be styled under the site’s existing policy. Do not loosen unrelated security rules.')
step(2,'Keep /widget embeddable. Do not apply a blanket X-Frame-Options DENY or SAMEORIGIN header to that route. Keep the staff login and dashboard protected against framing. The current app allows framing only on /widget; the production proxy must preserve that distinction.')
step(3,'Open the website on desktop and mobile, navigate between pages, refresh, and confirm only one chat button appears. Send a new message, reply from UOCSM, then confirm the reply appears in the website chat.')
step(4,'Test browser privacy restrictions. If embedded storage is blocked, offer a normal link to https://support.your-store.com/widget so the customer can open chat in its own tab.')
h('What is not shared automatically')
p('A website customer login does not sign an employee into UOCSM. The widget retains a browser-specific chat token, not a verified storefront customer identity. Do not trust a browser-supplied order owner or silently merge customer accounts.')
p('The existing manual order panel remains usable. For automatic order lookup, the developer must later agree on the store platform/API, server-to-server authentication, customer identity checks, order fields, update events and retry behavior. Do not connect the website directly to the support database or use an employee password as an API integration credential.')
p('Source: Next.js Script component documentation, reference 1 on page 10.')
page('3 Prepare the Meta connection')
p('Owner: the Meta manager, after the developer has completed the hosting handoff. Meta changes menu names; choose the WhatsApp, Messenger or Instagram messaging product/use case shown for your app. Account ownership and permissions can affect which options appear.')
h('Have these ready')
p('Access to the store’s Meta developer app and business assets; the public support URL; a supported Graph API version shown in Meta; and a password manager for tokens. If you do not own the asset or cannot grant access, the asset owner must complete that step.')
h('Configure inside UOCSM')
step(1,'Sign in as an administrator. Open Integrations, choose a channel, and select Configure connection. Agents cannot access this form.')
step(2,'Paste the public HTTPS support URL, account IDs and API version. Paste the access token and the app secret from the matching Meta app. A channel’s app secret must match the app that sends its webhooks.')
step(3,'Create a long random verification token in your password manager, paste it into the form, and retain the exact value. This token is one you choose; it is not your Meta access token, Facebook password or WhatsApp PIN.')
step(4,'Select Save connection. Copy the callback URL shown by UOCSM into Meta’s webhook settings. Enter the same verification token in Meta and select Verify and save.')
step(5,'Subscribe the correct business account or Page and the message event fields for that channel. Webhook verification alone does not subscribe the asset or prove real customer delivery.')
step(6,'Complete the channel-specific instructions on the next pages, then perform an inbound-and-reply test with a real permitted test account.')
h('Understand the status labels')
table(['Label','Meaning'],[['Not configured','Required account values are missing.'],['Configured awaiting webhook','Configuration is present; no matching live webhook has been observed.'],['Receiving webhooks','A matching webhook reached the adapter. Still verify an actual outbound reply.']],[2.1,4.8])
p('Saved secrets are encrypted in the database and never shown back in the form. Blank secret inputs retain existing values. Saving applies immediately. It does not register a number, grant Meta permissions, approve app review or send a test message.')
page('4 Connect WhatsApp Business')
p('This connects the WhatsApp Business Platform Cloud API. A WhatsApp Business mobile-app login by itself is not an API connection. Ask the account owner to confirm the number’s Cloud API registration or an eligible coexistence/migration path before changing an existing business number.')
table(['UOCSM field','Value to copy'],[['Phone Number ID','WhatsApp → API Setup → Phone number ID. This is an ID, not the displayed phone number.'],['WhatsApp Business Account ID','The WABA ID for the same business account.'],['Access token','A token with access to this number and WhatsApp messaging. Use a suitable system-user token for ongoing service; short-lived test tokens expire.'],['Meta app secret','Settings → Basic → App secret in the app used for this WhatsApp integration.']],[2.1,4.8])
h('Connection steps')
step(1,'In the Meta developer app, open the WhatsApp setup/use case. Select or create the store’s WhatsApp Business Account and identify the test or production number. Complete any registration and business requirements Meta displays.')
step(2,'Provide the matching IDs and token in UOCSM → Integrations → WhatsApp Business → Configure connection. The token needs whatsapp_business_messaging; account setup/subscription operations also use whatsapp_business_management.')
step(3,'Save the UOCSM form. In Meta’s WhatsApp webhook configuration, paste https://YOUR-SUPPORT-HOST/webhooks/whatsapp and your chosen verification token.')
step(4,'Verify the callback, subscribe to messages, and ensure the app is subscribed to the same WABA. If only the test event arrives, ask the developer to check the WABA app subscription.')
step(5,'For a Meta test number, add an allowed test recipient as prompted by Meta. Send a text from that recipient to the business number. Find it in the UOCSM inbox, send a reply, and confirm it arrives on the phone.')
h('Current limits')
p('Free-form replies are checked against a 24-hour customer reply window. Outside it, the application blocks the reply; approved-template sending is not implemented. Media currently appears as an unsupported-content placeholder. Test text first. A successful API acceptance is distinct from delivery or read confirmation.')
p('Source: Meta WhatsApp Cloud API collection, reference 2 on page 10. The listed UOCSM behavior describes this implementation.')
page('5 Connect Facebook Messenger')
p('This connects the store’s Facebook Page inbox, not a personal Facebook Messenger account. Use the Page and app that the business owns or is authorized to manage.')
table(['UOCSM field','Value to copy'],[['Facebook Page ID','The numeric ID of the store Page.'],['Access token','A Page access token for that exact Page, with messaging access.'],['Meta app secret','The secret for the app configured to receive this Page’s events.'],['Callback URL','https://YOUR-SUPPORT-HOST/webhooks/facebook']],[2.1,4.8])
h('Connection steps')
step(1,'In the Meta developer app, add or open the Messenger messaging use case/product. Connect the store’s Page using an account that can manage it.')
step(2,'Generate or obtain the Page token using the setup flow shown by Meta. Confirm pages_messaging access and the Page-management/subscription permissions required by your chosen setup flow, such as pages_manage_metadata. Do not substitute a personal user token.')
step(3,'Open UOCSM → Integrations → Facebook Messenger → Configure connection. Paste the Page ID, token, app secret, version and verification token. Save.')
step(4,'In Meta’s Page/Messenger webhook settings, enter the callback and verification token. Verify and save, then subscribe the Page to the app and enable messages, message_deliveries and message_reads where offered.')
step(5,'Use a permitted test user to send a new text to the Page. Confirm one conversation appears, send one reply, and confirm it arrives in Messenger.')
step(6,'Before accepting normal customers, complete the app mode, permissions, review and business requirements that Meta shows for this app. Test with an ordinary non-staff account after the required access is granted.')
h('Common mistakes')
p('The Page ID and Page access token must match. Callback verification does not prove the Page is subscribed. A built-in test notification can succeed while ordinary customers are still restricted by app access settings.')
p('This adapter supports ordinary text within its configured reply-window check. It does not implement message tags for extended windows, sponsored messages, comment replies, or full media handling. Unknown sends require investigation before resending.')
p('Source: Meta Messenger Platform API collection, reference 3 on page 10. Ask the developer for help if a subscription operation is only exposed through an API in your account.')
page('6 Connect Instagram messages')
p('Important: this application implements Instagram API with Instagram Login. Use a professional Instagram account and the corresponding Instagram user access token. Do not paste a Facebook Page token or follow the older Facebook Login connection path.')
table(['UOCSM field','Value to copy'],[['Instagram professional account ID','The numeric Instagram account ID shown by the Instagram API setup.'],['Access token','An Instagram user access token for that professional account.'],['Meta app secret','The app secret associated with this Instagram integration.'],['Callback URL','https://YOUR-SUPPORT-HOST/webhooks/instagram']],[2.1,4.8])
h('Connection steps')
step(1,'In the Meta developer app, choose Instagram API with Instagram Login. Connect the store’s professional account using the setup flow available to that account.')
step(2,'Grant the necessary messaging access. This path uses instagram_business_basic and instagram_business_manage_messages. Follow Meta’s test-account, token generation and permission instructions for this login path.')
step(3,'Open UOCSM → Integrations → Instagram → Configure connection. Paste the matching account ID, Instagram token, app secret and API version. Create or reuse this channel’s verification token and save.')
step(4,'In Meta’s Instagram webhook configuration, verify the callback with the same verification token. Subscribe the professional account and enable messages. Enable the relevant seen/read event if available; verify its behavior with the actual account.')
step(5,'Have a permitted test customer send a direct text message to the store account. Customers must initiate the conversation for this basic reply flow. Find the conversation in UOCSM and reply.')
step(6,'Confirm delivery in the customer’s Instagram inbox. Complete any additional access or app-review requirements shown by Meta before testing ordinary customer accounts.')
h('If a test works but real customers do not')
p('Check that the professional account is subscribed, that the token belongs to that account, and that the app has the access level needed for non-test users. Recheck whether the setup used Instagram Login rather than Facebook Login. If these differ, ask the developer to correct the connection path.')
p('This adapter uses graph.instagram.com and text replies. Full media, comment/private-reply automation and extended-window workflows are not implemented. Meta menu labels and eligibility requirements can vary.')
p('Source: Meta Instagram API collection, reference 4 on page 10.')
page('7 Employee access and dashboard meanings')
p('Employees open the support URL and sign in with their UOCSM account. Customers do not use this login. The home page is the Dashboard; Inbox remains a separate workspace for handling messages.')
table(['Dashboard item','Admin sees','Agent sees'],[['Conversation statistics','All store conversations','Only currently assigned conversations'],['Recent and waiting conversations','Store-wide permitted records','Only assigned records'],['Agent status and workload','All support agents','Not included'],['Channel identity and queue health','Store-wide channel data','Not included'],['Response time and satisfaction','Store-wide values','Values for assigned conversations']],[2.2,2.35,2.35])
h('Metric definitions')
p('Pending first reply means NEW. In process means OPEN. Closed means currently CLOSED; archived records are retained separately. Awaiting reply includes new conversations and open conversations with an unanswered-message deadline. Overdue identifies expired initial deadlines, escalated new records, or overdue reminder cycles.')
p('Current progress is closed conversations divided by all visible conversations. It is not a promise of work completed today. A reopened record leaves the closed count. Mean first response uses the first successful outgoing message for each conversation over its lifetime, not a separate value for every reopened episode.')
p('Activity charts cover seven calendar days in Asia/Karachi and distinguish received from successfully sent messages. Customer ratings currently come from website chat. Agent statistics follow current ownership, so reassignment moves the related history into or out of that agent’s dashboard.')
p('Active agents means enabled accounts. Available means enabled and marked available for assignment. Online means authenticated activity during the last two minutes. These are different measures; an available account may be offline.')
h('Admin operating routine')
step(1,'Create individual agents in Store settings. Set availability in Team members. Agents can change their passwords under Account; a change revokes their existing sessions.')
step(2,'Choose response deadlines and whether initial expiry archives a conversation or keeps it visible and alerts a manager. Business-hour text is informational; timers still run continuously.')
step(3,'At the start and end of each shift, review unassigned work, overdue cases, archived records and Queue health. Investigate failed or unknown sends before resending.')
page('8 Acceptance checklist and troubleshooting')
p('The Meta manager and one employee should complete this checklist for each channel. A green configuration label alone is not acceptance.')
step(1,'Send a unique test text from a permitted customer account. Confirm one conversation appears with the correct content and an assigned eligible agent.')
step(2,'Sign in as that agent. Confirm the conversation is visible and the dashboard counts it. Confirm another agent cannot open it and cannot see store-wide channel statistics.')
step(3,'Reply once from UOCSM and confirm arrival on the customer’s device. Check that the message is not left queued, failed or unknown.')
step(4,'Close the conversation. Confirm the closed count changes. Send a new customer message and confirm the conversation reopens with preserved history.')
step(5,'For website chat, also test mobile layout, navigation, refresh and the customer rating after closure. Confirm customers cannot access staff pages without a login.')
table(['Symptom','Next action'],[['Callback will not verify','Check public HTTPS reachability, exact route and identical verification token. Ask the developer to check proxy/firewall logs.'],['Configured but no customer messages','Check asset subscription, account ID, messaging permission and app/test-user access. A dashboard test is not enough.'],['Messages arrive but replies fail','Check token expiry, token/account match, allowed reply window and provider error. Review Queue health.'],['An event needs review','Keep its retained record. Ask the developer to correct the cause, then use Queue health → Retry retained event.'],['A send is UNKNOWN','Check the customer/provider outcome before retrying. An automatic resend could duplicate it.'],['Widget button is missing','Check script URL, site CSP and browser console. The developer can verify /embed.js and /widget directly.'],['Agent sees fewer numbers than admin','Expected: the API filters agents to their current assignments. Check assignment before treating it as missing data.']],[2.2,4.7])
p('Never delete records simply to make an error disappear. Keep a test log with channel, time, expected outcome and result, but do not paste access tokens into screenshots or support messages.')
page('9 Handoff record and references')
h('Fill in before go live')
table(['Item','Record here'],[['Public storefront URL','________________________________________'],['Employee support URL','________________________________________'],['Developer and hosting contact','________________________________________'],['Meta asset owner','________________________________________'],['Support administrator','________________________________________'],['WhatsApp test completed','Date __________  Result __________________'],['Instagram test completed','Date __________  Result __________________'],['Facebook test completed','Date __________  Result __________________'],['Website test completed','Date __________  Result __________________'],['Backup and restore owner','________________________________________']],[2.6,4.3])
